package com.autojobapply.matching;
import com.autojobapply.config.Config; import com.autojobapply.model.*; import java.util.*;
/** Deterministic, explainable scoring; terms and weights are deliberately visible. */
public final class JobMatcher {
 private static final List<String> SKILLS=List.of("java","spring","spring boot","microservices","kafka","distributed systems","aws","rest","sql","oracle","architecture","system design","event-driven","cloud","leadership"); private final Resume resume; private final ApplicantProfile profile; private final Config config;
 public JobMatcher(Resume r,ApplicantProfile p,Config c){resume=r;profile=p;config=c;}
 public ScoredJob score(Job j){String d=(j.title()+" "+j.description()).toLowerCase();List<String> asked=SKILLS.stream().filter(s->d.contains(s)).toList();List<String> hit=asked.stream().filter(s->resume.text().toLowerCase().contains(s)).toList();List<String> missing=asked.stream().filter(s->!hit.contains(s)).toList();double technical=asked.isEmpty()?0.5:(double)hit.size()/asked.size();double experience=containsBoth(d,"experience","year")&&resume.text().toLowerCase().contains("experience")?1:0.55; double architecture=containsAny(d,"architect","system design","distributed")&&containsAny(resume.text().toLowerCase(),"architect","system design","distributed")?1:0.45;double seniority=containsAny(resume.text().toLowerCase(),"principal","staff","lead","architect")?1:0.55;double domain=technical;int score=(int)Math.round(100*(technical*.35+experience*.25+architecture*.20+seniority*.10+domain*.10)); boolean eligible=score>=config.minimumScore()&&eligibility(j);String reason="skills "+hit.size()+"/"+asked.size()+", deterministic weighted score";return new ScoredJob(j,score,hit,missing,eligible,reason);}
 private boolean eligibility(Job j){String d=j.description().toLowerCase();if(d.contains("must be authorized")&&profile.get("work.authorization").isBlank())return false;return true;}private boolean containsBoth(String s,String a,String b){return s.contains(a)&&s.contains(b);}private boolean containsAny(String s,String...xs){return Arrays.stream(xs).anyMatch(s::contains);}
}
